p=argparse.ArgumentParser();p.add_argument('--url',default='http://127.0.0.1:8008');p.add_argument('--out',type=Path,required=True);p.add_argument('--seconds',type=int,default=12);p.add_argument('--expected-commit');p.add_argument('--counts',default='25,100,250,500,1000');a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
